* {{iter|}}
* {{iter|}}
</pre>

* {{iter|}}
* {{iter|}}
* {{iter|}}
* {{iter|}}

== Reset the counter ==

<pre>
* {{iter|reset=yes}}
* {{iter|}}
* {{iter|reset=yes}}
* {{iter|}}
</pre>

* {{iter|reset=yes}}
* {{iter|}}
* {{iter|reset=yes}}
* {{iter|}}

